60	/// Identify the top 1–2 cats as coordinators based on social weight, diligence,
61	/// and sociability. Runs once per in-game day or immediately when a coordinator
62	/// dies (cadence governed by `CoordinationConstants::evaluate_interval`).
63	#[allow(clippy::too_many_arguments)]
64	pub fn evaluate_coordinators(
65	    mut commands: Commands,
66	    time: Res<TimeState>,
67	    time_scale: Res<TimeScale>,
68	    coordinator_died: Option<Res<CoordinatorDied>>,
69	    query: Query<(Entity, &Personality, &Memory, &Name), Without<Dead>>,
70	    existing_coordinators: Query<Entity, With<Coordinator>>,
71	    relationships: Res<Relationships>,
72	    mut log: ResMut<NarrativeLog>,
73	    event_log: Option<ResMut<crate::resources::event_log::EventLog>>,
74	    constants: Res<SimConstants>,
75	    mut activation: ResMut<SystemActivation>,
76	) {
77	    let c = &constants.coordination;
78	    let should_run =
79	        coordinator_died.is_some() || c.evaluate_interval.fires_at(time.tick, &time_scale);
80	    if !should_run {
81	        return;
82	    }
83	
84	    let living_count = query.iter().count();
85	    let max_coordinators: usize = if living_count < c.small_colony_threshold {
86	        1
87	    } else {
88	        2
89	    };
90	    let threshold = c.promotion_threshold;
91	
92	    // Score all living cats.
93	    let mut candidates: Vec<(Entity, f32, String)> = query
94	        .iter()
95	        .map(|(entity, personality, memory, name)| {
96	            let sw = social_weight(entity, &relationships, memory, c);
97	            let score = sw
98	                * personality.diligence
99	                * personality.sociability
100	                * (1.0 + personality.ambition * c.ambition_bonus);
101	            (entity, score, name.0.clone())
102	        })
103	        .filter(|(_, score, _)| *score >= threshold)
104	        .collect();
105	
106	    // Sort by score descending, tiebreak by entity index for determinism.
107	    candidates.sort_by(|a, b| {
108	        b.1.partial_cmp(&a.1)
109	            .unwrap_or(std::cmp::Ordering::Equal)
110	            .then(a.0.index().cmp(&b.0.index()))
111	    });
112	    candidates.truncate(max_coordinators);
113	
114	    let new_set: Vec<Entity> = candidates.iter().map(|(e, _, _)| *e).collect();
115	
116	    // Remove Coordinator from cats who lost the role.
117	    for entity in &existing_coordinators {
118	        if !new_set.contains(&entity) {
119	            commands.entity(entity).remove::<Coordinator>();
120	            commands.entity(entity).remove::<DirectiveQueue>();
121	            commands.entity(entity).remove::<BuildPressure>();
122	            commands.entity(entity).remove::<PendingDelivery>();
123	        }
124	    }
125	
126	    // Add Coordinator + DirectiveQueue to new coordinators.
127	    let mut event_log = event_log;
128	    let mut new_coordinator_names: Vec<&str> = Vec::new();
129	    for (entity, score, name) in &candidates {
130	        if existing_coordinators.get(*entity).is_err() {
131	            commands.entity(*entity).insert((
132	                Coordinator,
133	                DirectiveQueue::default(),
134	                BuildPressure::default(),
135	            ));
136	            new_coordinator_names.push(name.as_str());
137	            if let Some(ref mut elog) = event_log {
138	                elog.push(
139	                    time.tick,
140	                    crate::resources::event_log::EventKind::CoordinatorElected {
141	                        cat: name.clone(),
142	                        social_weight: *score,
143	                    },
144	                );
145	            }
146	        }
147	    }
148	
149	    // Emit a single combined narrative line for all new coordinators.
150	    if !new_coordinator_names.is_empty() {
151	        activation.record(Feature::CoordinatorElected);
152	        let names = match new_coordinator_names.len() {
153	            1 => new_coordinator_names[0].to_string(),
154	            2 => format!(
155	                "{} and {}",
156	                new_coordinator_names[0], new_coordinator_names[1]
157	            ),
158	            _ => {
159	                let (last, rest) = new_coordinator_names.split_last().unwrap();
160	                format!("{}, and {last}", rest.join(", "))
161	            }
162	        };
163	        log.push(
164	            time.tick,
165	            format!("The others look to {names} when decisions need making."),
166	            NarrativeTier::Significant,
167	        );
168	    }
169	
170	    // Clear the flag if it was set.
171	    if coordinator_died.is_some() {
172	        commands.remove_resource::<CoordinatorDied>();
173	    }
174	}
175	
176	// ---------------------------------------------------------------------------
177	// WardPlacementSignals — bundles the four spatial inputs the perimeter
178	// scoring loop reads. Lives here to keep `assess_colony_needs` under
179	// Bevy's 16-param tuple limit per CLAUDE.md guidance.

